initJs:
function(container, apiUrl, tables) {
  const salesTable = tables[0]; // 売上実績データ
  const storeTable = tables[1]; // 店舗マスタ
  const productTable = tables[2]; // 商品マスタ

  let allSalesData = [];
  let allStores = [];
  let allProducts = [];

  // 曜日変換
  const getDayOfWeek = (dateStr) => {
    const days = ['日', '月', '火', '水', '木', '金', '土'];
    const date = new Date(dateStr);
    return days[date.getDay()];
  };

  // 金額フォーマット
  const formatAmount = (amount) => {
    return new Intl.NumberFormat('ja-JP').format(amount);
  };

  // 店舗名取得
  const getStoreName = (storeId) => {
    const store = allStores.find(s => s.id === storeId);
    return store ? store.店舗名 : '不明';
  };

  // 商品名取得
  const getProductName = (productId) => {
    const product = allProducts.find(p => p.id === productId);
    return product ? product.商品名 : '不明';
  };

  // テーブル再描画
  function renderRows(rows) {
    const tbody = container.querySelector('#sales-tbody');
    tbody.innerHTML = rows.map(row => `
      <tr data-id="${row.id}">
        <td>${row.売上日 ? new Date(row.売上日).toLocaleDateString('ja-JP') : ''}</td>
        <td>${getStoreName(row.店舗ID)}</td>
        <td>${getProductName(row.商品ID)}</td>
        <td>${formatAmount(row.販売数量 || 0)}</td>
        <td>¥${formatAmount(row.単価 || 0)}</td>
        <td>¥${formatAmount(row.売上金額 || 0)}</td>
        <td>${getDayOfWeek(row.売上日)}</td>
        <td>${row.特売フラグ ? '特売' : '通常'}</td>
        <td>
          <button class="action-btn secondary edit-btn" data-id="${row.id}">編集</button>
          <button class="action-btn secondary delete-btn" data-id="${row.id}">削除</button>
        </td>
      </tr>
    `).join('');
  }

  // ドロップダウン初期化
  function initDropdowns() {
    const filterStore = container.querySelector('#filter-store');
    const filterProduct = container.querySelector('#filter-product');
    const formStore = container.querySelector('#form-store');
    const formProduct = container.querySelector('#form-product');

    // 店舗選択肢
    allStores.forEach(store => {
      if (store.有効フラグ) {
        const option1 = new Option(store.店舗名, store.id);
        const option2 = new Option(store.店舗名, store.id);
        filterStore.appendChild(option1);
        formStore.appendChild(option2);
      }
    });

    // 商品選択肢
    allProducts.forEach(product => {
      if (product.有効フラグ) {
        const option1 = new Option(product.商品名, product.id);
        const option2 = new Option(product.商品名, product.id);
        filterProduct.appendChild(option1);
        formProduct.appendChild(option2);
      }
    });
  }

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      const [salesData, storeData, productData] = await Promise.all([
        window.aivicApi.list(0),
        window.aivicApi.list(1),
        window.aivicApi.list(2)
      ]);

      allSalesData = salesData || salesTable.records || [];
      allStores = storeData || storeTable.records || [];
      allProducts = productData || productTable.records || [];

      initDropdowns();
      renderRows(allSalesData);
    } catch (error) {
      console.error('データ読み込みエラー:', error);
      allSalesData = salesTable.records || [];
      allStores = storeTable.records || [];
      allProducts = productTable.records || [];
      initDropdowns();
      renderRows(allSalesData);
    }
  }

  // 検索・絞り込み
  container.querySelector('#btn-search').addEventListener('click', async () => {
    const storeId = container.querySelector('#filter-store').value;
    const productId = container.querySelector('#filter-product').value;
    const startDate = container.querySelector('#filter-date-start').value;
    const endDate = container.querySelector('#filter-date-end').value;

    try {
      const rows = await window.aivicApi.list(0);
      let filtered = rows || [];

      if (storeId) {
        filtered = filtered.filter(r => r.店舗ID === storeId);
      }
      if (productId) {
        filtered = filtered.filter(r => r.商品ID === productId);
      }
      if (startDate) {
        filtered = filtered.filter(r => r.売上日 >= startDate);
      }
      if (endDate) {
        filtered = filtered.filter(r => r.売上日 <= endDate);
      }

      renderRows(filtered);
    } catch (error) {
      console.error('検索エラー:', error);
    }
  });

  // 新規登録ボタン
  container.querySelector('#btn-new').addEventListener('click', () => {
    container.querySelector('#modal-title').textContent = '売上実績登録';
    container.querySelector('#edit-id').value = '';
    container.querySelector('#sales-form').reset();
    container.querySelector('#sales-modal').classList.remove('hidden');
  });

  // モーダル閉じる
  container.querySelector('#modal-close').addEventListener('click', () => {
    container.querySelector('#sales-modal').classList.remove('hidden');
  });

  container.querySelector('#btn-cancel').addEventListener('click', () => {
    container.querySelector('#sales-modal').classList.add('hidden');
  });

  // 売上金額自動計算
  const updateAmount = () => {
    const quantity = parseFloat(container.querySelector('#form-quantity').value) || 0;
    const price = parseFloat(container.querySelector('#form-price').value) || 0;
    container.querySelector('#form-amount').value = quantity * price;
  };

  container.querySelector('#form-quantity').addEventListener('input', updateAmount);
  container.querySelector('#form-price').addEventListener('input', updateAmount);

  // フォーム保存
  container.querySelector('#sales-form').addEventListener('submit', async (e) => {
    e.preventDefault();

    const formData = {
      店舗ID: container.querySelector('#form-store').value,
      商品ID: container.querySelector('#form-product').value,
      売上日: container.querySelector('#form-date').value,
      販売数量: parseInt(container.querySelector('#form-quantity').value),
      単価: parseInt(container.querySelector('#form-price').value),
      売上金額: parseInt(container.querySelector('#form-amount').value),
      特売フラグ: container.querySelector('#form-sale').value === 'true',
      割引率: parseInt(container.querySelector('#form-discount').value) || 0,
      曜日区分: new Date(container.querySelector('#form-date').value).getDay() + 1,
      祝日フラグ: false,
      在庫切れフラグ: false,
      データ取込日時: new Date().toISOString(),
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString(),
      作成者ID: 'current-user'
    };

    // バリデーション
    if (!formData.店舗ID) {
      alert('店舗を選択してください');
      return;
    }
    if (!formData.商品ID) {
      alert('商品を選択してください');
      return;
    }
    if (!formData.売上日) {
      alert('売上日を入力してください');
      return;
    }
    if (new Date(formData.売上日) > new Date()) {
      alert('未来の日付は入力できません');
      return;
    }
    if (formData.販売数量 < 0) {
      alert('売上数量は0以上の値を入力してください');
      return;
    }
    if (formData.単価 < 0) {
      alert('単価は0以上の値を入力してください');
      return;
    }

    try {
      const editId = container.querySelector('#edit-id').value;
      if (editId) {
        await window.aivicApi.update(0, editId, formData);
      } else {
        await window.aivicApi.save(0, formData);
      }

      container.querySelector('#sales-modal').classList.add('hidden');
      const updatedRows = await window.aivicApi.list(0);
      renderRows(updatedRows);
    } catch (error) {
      console.error('保存エラー:', error);
      alert('保存に失敗しました');
    }
  });

  // 行レベル操作（編集・削除）
  container.addEventListener('click', async (e) => {
    const editBtn = e.target.closest('.edit-btn');
    const deleteBtn = e.target.closest('.delete-btn');

    if (editBtn) {
      const id = editBtn.dataset.id;
      const row = allSalesData.find(r => r.id === id);
      if (!row) {
        alert('指定されたデータが見つかりません');
        return;
      }

      container.querySelector('#modal-title').textContent = '売上実績編集';
      container.querySelector('#edit-id').value = id;
      container.querySelector('#form-store').value = row.店舗ID || '';
      container.querySelector('#form-product').value = row.商品ID || '';
      container.querySelector('#form-date').value = row.売上日 ? row.売上日.split('T')[0] : '';
      container.querySelector('#form-quantity').value = row.販売数量 || '';
      container.querySelector('#form-price').value = row.単価 || '';
      container.querySelector('#form-amount').value = row.売上金額 || '';
      container.querySelector('#form-sale').value = row.特売フラグ ? 'true' : 'false';
      container.querySelector('#form-discount').value = row.割引率 || 0;
      container.querySelector('#sales-modal').classList.remove('hidden');
    }

    if (deleteBtn) {
      const id = deleteBtn.dataset.id;
      if (!confirm('この売上実績データを削除しますか？')) return;

      try {
        await window.aivicApi.delete(0, id);
        const updatedRows = await window.aivicApi.list(0);
        renderRows(updatedRows);
      } catch (error) {
        console.error('削除エラー:', error);
        alert('指定されたデータが存在しません');
      }
    }
  });

  // CSVエクスポート
  container.querySelector('#btn-export').addEventListener('click', async () => {
    try {
      const rows = await window.aivicApi.list(0);
      const headers = ['売上日', '店舗名', '商品名', '販売数量', '単価', '売上金額', '曜日', '特売フラグ'];
      const csvData = [
        headers.join(','),
        ...rows.map(row => [
          row.売上日 ? new Date(row.売上日).toLocaleDateString('ja-JP') : '',
          `"${getStoreName(row.店舗ID)}"`,
          `"${getProductName(row.商品ID)}"`,
          row.販売数量 || 0,
          row.単価 || 0,
          row.売上金額 || 0,
          getDayOfWeek(row.売上日),
          row.特売フラグ ? '特売' : '通常'
        ].join(','))
      ].join('\n');

      const blob = new Blob(['\uFEFF' + csvData], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `売上実績_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();
    } catch (error) {
      console.error('エクスポートエラー:', error);
    }
  });

  // インポートモーダル
  container.querySelector('#btn-import').addEventListener('click', () => {
    container.querySelector('#import-modal').classList.remove('hidden');
  });

  container.querySelector('#import-close').addEventListener('click', () => {
    container.querySelector('#import-modal').classList.add('hidden');
  });

  // テンプレートダウンロード
  container.querySelector('#btn-template').addEventListener('click', () => {
    const headers = ['店舗ID', '商品ID', '売上日', '販売数量', '単価', '売上金額', '特売フラグ', '割引率'];
    const csvData = headers.join(',');
    const blob = new Blob(['\uFEFF' + csvData], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = '売上実績テンプレート.csv';
    link.click();
  });

  // ドラッグ&ドロップ
  const dropZone = container.querySelector('#drop-zone');
  const fileInput = container.querySelector('#csv-file');

  dropZone.addEventListener('click', () => fileInput.click());
  dropZone.addEventListener('dragover', (e) => {
    e.preventDefault();
    dropZone.classList.add('dragover');
  });
  dropZone.addEventListener('dragleave', () => {
    dropZone.classList.remove('dragover');
  });
  dropZone.addEventListener('drop', (e) => {
    e.preventDefault();
    dropZone.classList.remove('dragover');
    const files = e.dataTransfer.files;
    if (files.length > 0) {
      handleFile(files[0]);
    }
  });

  fileInput.addEventListener('change', (e) => {
    if (e.target.files.length > 0) {
      handleFile(e.target.files[0]);
    }
  });

  function handleFile(file) {
    if (!file.name.endsWith('.csv')) {
      alert('CSVファイルを選択してください');
      return;
    }

    const reader = new FileReader();
    reader.onload = (e) => {
      const csv = e.target.result;
      const lines = csv.split('\n').filter(line => line.trim());
      if (lines.length < 2) {
        alert('データが含まれていません');
        return;
      }

      const headers = lines[0].split(',');
      const previewData = lines.slice(1, 11); // 最初の10行のみプレビュー

      // プレビューテーブル表示
      const previewThead = container.querySelector('#preview-thead');
      const previewTbody = container.querySelector('#preview-tbody');

      previewThead.innerHTML = `<tr>${headers.map(h => `<th>${h}</th>`).join('')}</tr>`;
      previewTbody.innerHTML = previewData.map(line => {
        const cells = line.split(',');
        return `<tr>${cells.map(cell => `<td>${cell}</td>`).join('')}</tr>`;
      }).join('');

      container.querySelector('#preview-section').classList.remove('hidden');
    };
    reader.readAsText(file);
  }

  // 一括インポート実行
  container.querySelector('#btn-bulk-import').addEventListener('click', async () => {
    const file = fileInput.files[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = async (e) => {
      const csv = e.target.result;
      const lines = csv.split('\n').filter(line => line.trim());
      const dataLines = lines.slice(1);

      let imported = 0;
      let failed = 0;

      for (const line of dataLines) {
        const cells = line.split(',');
        if (cells.length < 6) continue;

        const rowData = {
          店舗ID: cells[0]?.trim(),
          商品ID: cells[1]?.trim(),
          売上日: cells[2]?.trim(),
          販売数量: parseInt(cells[3]) || 0,
          単価: parseInt(cells[4]) || 0,
          売上金額: parseInt(cells[5]) || 0,
          特売フラグ: cells[6]?.trim() === 'true',
          割引率: parseInt(cells[7]) || 0,
          曜日区分: new Date(cells[2]).getDay() + 1,
          祝日フラグ: false,
          在庫切れフラグ: false,
          データ取込日時: new Date().toISOString(),
          作成日時: new Date().toISOString(),
          更新日時: new Date().toISOString(),
          作成者ID: 'current-user'
        };

        try {
          await window.aivicApi.save(0, rowData);
          imported++;
        } catch (error) {
          failed++;
        }
      }

      alert(`インポート完了\n成功: ${imported}件\n失敗: ${failed}件`);
      container.querySelector('#import-modal').classList.add('hidden');
      const updatedRows = await window.aivicApi.list(0);
      renderRows(updatedRows);
    };
    reader.readAsText(file);
  });

  // 初期化実行
  loadInitialData();
}
